main:
    // Standard function prologue
    stp     x29, x30, [sp, #-32]!
    mov     x29, sp

    //----------------------------------------------------------------------------
    // This example demonstrates some SVE operations using the instructions:
    //   • rdvl      – read the (scalable) vector length multiplied by an immediate
    //   • ptrue     – set a predicate register to “all true”
    //   • index     – generate an increasing index vector
    //   • lsr       – vector logical shift right (predicated)
    //   • cntw/cnth – count the number of active 32‐bit elements / 16‐bit elements
    //   • ld1b      – load contiguous bytes into a vector register
    //   • uaddv     – unsigned horizontal add reduction
    //
    // The code below uses these instructions to load an array of 16 bytes from
    // a constant “mydata”, create an index vector and a shifted version of it,
    // reduce (sum horizontally) both vectors, add the two results together and
    // then print the final result using printf (with format string "%d\n").
    //----------------------------------------------------------------------------

    // Set up predicate registers:
    ptrue   p0.b               // p0: all byte‐elements active
    ptrue   p1.s               // p1: all 32‐bit (word) elements active

    // Read the scalable vector length (in bytes) multiplied by 1.
    rdvl    x2, #1             // x2 := VL (in bytes)

    // Create an index vector in Z0 (each lane is a 32‐bit integer)
    index   z0.s, #0, #1       // z0.s := { 0, 1, 2, … }

    // Shift the index vector right by 1 (using p0 to mask all lanes)
    lsr     z1.s, p0/m, z0.s, #1   // z1.s := z0.s >> 1

    // Count the number of active 32‐bit lanes.
    cntw    w3, ptrue        // w3 := (active number of 32‐bit elements) 
                           // (The immediate multiplier is defaulted here.)
    // Count the number of active 16‐bit lanes.
    cnth    w4, ptrue        // w4 := (active number of 16‐bit elements)

    // Load 16 contiguous bytes from memory (the data in "mydata") into Z2.
    adrp    x0, mydata
    add     x0, x0, :lo12:mydata
    ld1b    {z2.b}, p0/z, [x0]   // load vector of bytes from mydata into Z2

    // Horizontally reduce (add) the bytes in Z2.
    uaddv   s5, p0, z2.b     // s5 := sum{ each byte in Z2 }, with zero‐extension

    // Also horizontally reduce the shifted index vector (Z1) for demonstration.
    uaddv   s6, p0, z1.s     // s6 := sum{ each element in Z1 }

    // Combine the two scalar sums.
    add     s7, s5, s6       // s7 := s5 + s6

    // Prepare for the call to printf. We will print the computed sum.
    adrp    x1, fmt
    add     x1, x1, :lo12:fmt
    mov     x0, x1         // First argument to printf: pointer to the format string "%d\n"
    mov     w1, s7         // Second argument: our computed sum (s7 is 32-bit)
    bl      printf

    // Function epilogue: return 0.
    mov     w0, wzr
    ldp     x29, x30, [sp], #32
    ret

