        asr     z5.d, p0/M, z4.d, #63
        // * Compute bitwise NOT of z5 so that nonnegative lanes get all ones and negative lanes get 0.
        not     z5.d, p0/M, z5.d
        // * And together: if z4 was negative then z4 becomes 0.
        and     z4.d, p0/M, z4.d, z5.d

