    cntw    x3              // number of 32-bit lanes in the current vector
    add     x1, x1, x3
    cmp     x1, x4
    blt     1b

    // ---------- End of vectorized loop ------------
    // For demonstration, load the first computed 32-bit value and print it.
    ldr     w1, [x0]
    adrp    x0, .L_str
    add     x0, x0, :lo12:.L_str
    bl      printf

    // Return 0
    mov     w0, wzr
    ldp     x29, x30, [sp], #16
    ret
