    udiv   x9, x8, x21
    msub   x1, x9, x21, x8
    bl     printf

    // Epilogue: restore registers and stack.
    mov    w0, wzr
    add    sp, sp, #4000
    ldp    x20, x19, [sp, #80]
    ldp    x22, x21, [sp, #64]
    ldp    x24, x23, [sp, #48]
    ldp    x26, x25, [sp, #32]
    ldp    x28, x27, [sp, #16]
    ldp    x29, x30, [sp], #96
