	// Use x0 as base pointer for our vectorized processing.
	// We will process 1,000,000 32‐bit words.
	mov	x8, x0			// x8 = base pointer
	// rdvl computes the current vector length in bytes.
	rdvl	x2, #1		// x2 = VL in bytes

	// Number of 32‐bit elements per vector = VL/4.
	asr	x5, x2, #2		// x5 = (x2 >> 2); each element is 4 bytes

	// Set up loop counter: total number of words = 1,000,000.
	mov	x6, #1000000		

	// Initialize accumulator in x7.
	mov	x7, #0		

	// Set predicate p0 for 32‐bit elements to “all active”.
	ptrue	p0.s			

