	ld1w	{z0.s}, p0/z, [x8]

	// Perform a predicated logical shift right on each element.
	// This shifts each active element in z0.s by 1 bit.
	lsr	z0.s, p0, z0.s, #1	

	// Sum horizontally the elements in z0.s.
	// uaddv reduces (unsigned) across all active lanes.
	uaddv	s1, p0, z0.s		
