	ptrue   p0.s

	// Use cntw and cnth to count the active lanes.
	// cntw multiplies the number of active lanes (for 32‐bit elements) by the immediate.
	cntw    w10, p0.s, #1      // w10 = count of 32‐bit lanes
	cnth    w11, p0.h, #1      // w11 = count of 16‐bit lanes

	// Create a vector of consecutive integers: z0.s = {0, 1, 2, …}
	index   z0.s, #0, #1

	// Duplicate the constant 4 into each lane of z1.
	dup     z1.s, #4

	// Compute vector “square”:
	// Start by zeroing z2 and then do: z2.s = z0.s * z0.s
	dup     z2.s, #0
	mad     z2.s, p0/m, z0.s, z0.s

	// Compute vector “minus index”: z3.s = –z0.s
	neg     z3.s, p0/m, z0.s

	// Use movprfx to merge the negated vector into z4.
	movprfx z4.s, p0/m, z3.s
	// Multiply-add so that: z4.s = (–z0.s) + (z0.s * 4) = 3*z0.s
	mad     z4.s, p0/m, z0.s, z1.s

	// Horizontally reduce the two vectors.
	// uaddv does an unsigned add reduction across the active lanes.
	uaddv   d5, p0, z2.s      // d5 = sum of squares (i²)
	uaddv   d6, p0, z4.s      // d6 = sum of 3×i

