    // (Constants come from:
    //   k1 = (43690<<16)|43691,  k2 = (21845<<16)|21846,
    //   k3 = (52428<<16)|52429,  k4 = (13107<<16)|13108,
    //   k5 = (61166<<16)|61167,  k6 = (4369<<16)|4370.)
