    mov     x13, #21846
    mov     x14, #52429
    mov     x15, #13108
    mov     x16, #61167
    mov     x17, #4370
    movk    x12, #43690, lsl #16
    movk    x13, #21845, lsl #16
    movk    x14, #52428, lsl #16
    movk    x15, #13107, lsl #16
    movk    x16, #61166, lsl #16
    movk    x17, #4369,  lsl #16

    // Set up scalar accumulators.
    mov     x19, xzr           // acc12 = 0
    mov     x20, xzr           // acc3  = 0

    // --- SVE setup ---
    // Create a predicate covering “all” lanes for 32–bit elements.
    ptrue   p0.s

    // Use cntw to set (in x10) the number of active 32–bit lanes.
    cntw    x10, p0.s

    // Use rdvl (dummy use) to get the VL (in bytes).
    rdvl    x7, #1            // x7 = VL (in bytes)

    // Use cnth (dummy use) for 16–bit lanes.
    cnth    x8, p0.h

    // Use INDEX with an immediate stride value of 2.
    index   z17.s, #0, #2
    lsr     z17.s, p0/m, z17.s, #1

    // Initialize our loop–base (starting index for the 0–to–999 loop).
    mov     x0, xzr

