    mov     x9, #1000
    sub     x9, x9, x0

    // Compute x11 = min(x10, x9) (block count).
    cmp     x10, x9
    csel    x11, x10, x9, lo

    // Set up predicate p1 for the “live” lanes in this block.
    // (These lanes cover indices [x0, 1000).)
