    dup     z2.s, w13            // z2.s ← constant k2
    dup     z3.s, w14            // z3.s ← constant k3
    dup     z4.s, w15            // z4.s ← constant k4
    dup     z5.s, w16            // z5.s ← constant k5
    dup     z6.s, w17            // z6.s ← constant k6

