        stp     x29, x30, [sp, #-16]! 
        mov     x29, sp

        // Create a predicate for 64‐bit (doubleword) elements.
        ptrue   p0.d

        // Demonstrate counting the number of active predicate elements.
        // cntd counts the number of active double‐word lanes.
        cntd    x1, p0       // x1 := number of active 64‐bit lanes.
        // cntw counts the number of active 32‐bit lanes.
        cntw    x2, p0       // x2 := number of active 32‐bit lanes.

        // For demonstration, reverse the order of the predicate elements.
        rev     p1, p0

        // Load a vector of 64‐bit integers from an array.
